validator:
function validate(input) {
  const [{ Variables = [], Expressions = [] }] = input;
  const names = new Set(), triples = new Set();
  for (const [name, value] of Variables) {
    if (name === null || value === null) return 'Every variable needs a name and a value.';
    if (names.has(name.toLowerCase())) return `Variable ${name} appears twice.`;
    names.add(name.toLowerCase());
  }
  for (const [left, op, right] of Expressions) {
    if (!['>', '<', '='].includes(op)) return "operator must be '>', '<' or '='.";
    if (left === null || right === null || !names.has(left.toLowerCase()) || !names.has(right.toLowerCase())) return 'Every operand must be a variable in Variables.';
    const key = `${left.toLowerCase()} ${op} ${right.toLowerCase()}`;
    if (triples.has(key)) return `Expression ${key} appears twice.`;
    triples.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  let pool = small ? ['x', 'y', 'z', 'a', 'b'] : [];
  if (!small) {
    for (const c of letters) pool.push(c);
    for (const c of letters) for (const d of letters) pool.push(c + d);
  }
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const count = small ? Math.floor(rand() * 5) : 300;
  const values = [-3, 0, 5, 5, 66, 77];
  const Variables = pool.slice(0, count).map(name => [name, small ? values[Math.floor(rand() * values.length)] : Math.floor(rand() * 41) - 20]);
  const Expressions = [], seen = new Set(), ops = ['>', '<', '='];
  const wanted = !Variables.length ? 0 : small ? Math.floor(rand() * 9) : 2000;
  for (let tries = 0; Expressions.length < wanted && tries < wanted * 10; tries++) {
    const left = Variables[Math.floor(rand() * Variables.length)][0], right = Variables[Math.floor(rand() * Variables.length)][0];
    const op = ops[Math.floor(rand() * 3)], key = `${left} ${op} ${right}`;
    if (seen.has(key)) continue;
    seen.add(key);
    Expressions.push([left, op, right]);
  }
  return [{ Variables, Expressions }];
}
